 Begin CmpMap 	# Compound Mapping
    Nin = 1 	# Number of input coordinates
 IsA Mapping 	# Mapping between coordinate systems
    MapA = 	# First component Mapping
       Begin CmpMap 	# Compound Mapping
          Nin = 1 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          MapA = 	# First component Mapping
             Begin CmpMap 	# Compound Mapping
                Nin = 1 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                MapA = 	# First component Mapping
                   Begin CmpMap 	# Compound Mapping
                      Nin = 1 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                      MapA = 	# First component Mapping
                         Begin CmpMap 	# Compound Mapping
                            Nin = 1 	# Number of input coordinates
                         IsA Mapping 	# Mapping between coordinate systems
                            MapA = 	# First component Mapping
                               Begin CmpMap 	# Compound Mapping
                                  Nin = 1 	# Number of input coordinates
                               IsA Mapping 	# Mapping between coordinate systems
                                  MapA = 	# First component Mapping
                                     Begin CmpMap 	# Compound Mapping
                                        Nin = 1 	# Number of input coordinates
                                     IsA Mapping 	# Mapping between coordinate systems
                                        MapA = 	# First component Mapping
                                           Begin CmpMap 	# Compound Mapping
                                              Nin = 1 	# Number of input coordinates
                                           IsA Mapping 	# Mapping between coordinate systems
                                              MapA = 	# First component Mapping
                                                 Begin CmpMap 	# Compound Mapping
                                                    Nin = 1 	# Number of input coordinates
                                                 IsA Mapping 	# Mapping between coordinate systems
                                                    MapA = 	# First component Mapping
                                                       Begin CmpMap 	# Compound Mapping
                                                          Nin = 1 	# Number of input coordinates
                                                       IsA Mapping 	# Mapping between coordinate systems
                                                          MapA = 	# First component Mapping
                                                             Begin CmpMap 	# Compound Mapping
                                                                Nin = 1 	# Number of input coordinates
                                                             IsA Mapping 	# Mapping between coordinate systems
                                                                MapA = 	# First component Mapping
                                                                   Begin ZoomMap 	# Zoom about the origin
                                                                      Nin = 1 	# Number of input coordinates
                                                                   IsA Mapping 	# Mapping between coordinate systems
                                                                      Zoom = 2 	# Zoom factor
                                                                   End ZoomMap
                                                                MapB = 	# Second component Mapping
                                                                   Begin ZoomMap 	# Zoom about the origin
                                                                      Nin = 1 	# Number of input coordinates
                                                                   IsA Mapping 	# Mapping between coordinate systems
                                                                      Zoom = 1.5 	# Zoom factor
                                                                   End ZoomMap
                                                             End CmpMap
                                                          MapB = 	# Second component Mapping
                                                             Begin ZoomMap 	# Zoom about the origin
                                                                Nin = 1 	# Number of input coordinates
                                                             IsA Mapping 	# Mapping between coordinate systems
                                                                Zoom = 1.5 	# Zoom factor
                                                             End ZoomMap
                                                       End CmpMap
                                                    MapB = 	# Second component Mapping
                                                       Begin ZoomMap 	# Zoom about the origin
                                                          Nin = 1 	# Number of input coordinates
                                                       IsA Mapping 	# Mapping between coordinate systems
                                                          Zoom = 1.5 	# Zoom factor
                                                       End ZoomMap
                                                 End CmpMap
                                              MapB = 	# Second component Mapping
                                                 Begin ZoomMap 	# Zoom about the origin
                                                    Nin = 1 	# Number of input coordinates
                                                 IsA Mapping 	# Mapping between coordinate systems
                                                    Zoom = 1.5 	# Zoom factor
                                                 End ZoomMap
                                           End CmpMap
                                        MapB = 	# Second component Mapping
                                           Begin ZoomMap 	# Zoom about the origin
                                              Nin = 1 	# Number of input coordinates
                                           IsA Mapping 	# Mapping between coordinate systems
                                              Zoom = 1.5 	# Zoom factor
                                           End ZoomMap
                                     End CmpMap
                                  MapB = 	# Second component Mapping
                                     Begin ZoomMap 	# Zoom about the origin
                                        Nin = 1 	# Number of input coordinates
                                     IsA Mapping 	# Mapping between coordinate systems
                                        Zoom = 1.5 	# Zoom factor
                                     End ZoomMap
                               End CmpMap
                            MapB = 	# Second component Mapping
                               Begin ZoomMap 	# Zoom about the origin
                                  Nin = 1 	# Number of input coordinates
                               IsA Mapping 	# Mapping between coordinate systems
                                  Zoom = 1.5 	# Zoom factor
                               End ZoomMap
                         End CmpMap
                      MapB = 	# Second component Mapping
                         Begin ZoomMap 	# Zoom about the origin
                            Nin = 1 	# Number of input coordinates
                         IsA Mapping 	# Mapping between coordinate systems
                            Zoom = 1.5 	# Zoom factor
                         End ZoomMap
                   End CmpMap
                MapB = 	# Second component Mapping
                   Begin ZoomMap 	# Zoom about the origin
                      Nin = 1 	# Number of input coordinates
                   IsA Mapping 	# Mapping between coordinate systems
                      Zoom = 1.5 	# Zoom factor
                   End ZoomMap
             End CmpMap
          MapB = 	# Second component Mapping
             Begin ZoomMap 	# Zoom about the origin
                Nin = 1 	# Number of input coordinates
             IsA Mapping 	# Mapping between coordinate systems
                Zoom = 1.5 	# Zoom factor
             End ZoomMap
       End CmpMap
    MapB = 	# Second component Mapping
       Begin ZoomMap 	# Zoom about the origin
          Nin = 1 	# Number of input coordinates
       IsA Mapping 	# Mapping between coordinate systems
          Zoom = 1.5 	# Zoom factor
       End ZoomMap
 End CmpMap
